package com.spaceagent.platform.artifact.infrastructure.persistence;import com.spaceagent.platform.artifact.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres")public class PostgresArtifactRepository implements ArtifactRepository{private final JdbcTemplate j;public PostgresArtifactRepository(JdbcTemplate j){this.j=j;}public void save(Artifact a){j.update("INSERT INTO platform_artifacts(id,tenant_id,project_id,task_id,agent_run_id,workspace_id,artifact_type,name,content_ref,content_hash,summary,metadata_json,created_at) VALUES(CAST(? AS UUID),?,CAST(? AS UUID),CAST(? AS UUID),?,CAST(? AS UUID),?,?,?,?,?,?,?)",a.id(),a.tenantId(),a.projectId(),a.taskId(),a.agentRunId(),a.workspaceId(),a.type().name(),a.name(),a.contentRef(),a.contentHash(),a.summary(),a.metadataJson(),Timestamp.from(a.createdAt()));}public Optional<Artifact> findById(String id){return j.query("SELECT * FROM platform_artifacts WHERE id=CAST(? AS UUID)",this::map,id).stream().findFirst();}public List<Artifact> findByRunId(String id){return j.query("SELECT * FROM platform_artifacts WHERE agent_run_id=? ORDER BY created_at,id",this::map,id);}public List<Artifact> findByTaskId(String id){return j.query("SELECT * FROM platform_artifacts WHERE task_id=CAST(? AS UUID) ORDER BY created_at,id",this::map,id);}private Artifact map(ResultSet r,int n)throws SQLException{return new Artifact(r.getString("id"),r.getString("tenant_id"),r.getString("project_id"),r.getString("task_id"),r.getString("agent_run_id"),r.getString("workspace_id"),ArtifactType.valueOf(r.getString("artifact_type")),r.getString("name"),r.getString("content_ref"),r.getString("content_hash"),r.getString("summary"),r.getString("metadata_json"),r.getTimestamp("created_at").toInstant());}}
